fn is_keyword(s: Str) -> Bool {
  return s == "fn" || s == "let" || s == "return" || s == "if" || s == "else" || s == "while" || s == "for" || s == "match" || s == "pub";
}

fn is_integer(s: Str) -> Bool {
  for c in s.chars() {
    if c < '0' || c > '9' { return false; }
  }
  return s.len() > 0;
}

fn classify(s: Str) -> Str {
  if is_keyword(s) { return "keyword"; }
  if is_integer(s) { return "integer"; }
  if s.len() == 1 && "+-*/().:;}{,=<>!".contains(s) { return "operator"; }
  return "identifier";
}

fn main() -> Int {
  return classify("fn").len();
}
